    import random
    import time

    LANGUAGE_WRAPPER = 'A photo album contains {num_photos} photos, each showing exactly three people. In every photo: (i) the person on the left is a full brother of the person in the middle, and (ii) the person on the right is a daughter of the person in the middle. The person in the middle is different in each of the {num_photos} photos, and no two people who appear in the album are coparents of any child (that is, no pair of people in the album share a child). Across all photos, the daughters collectively occupy exactly {num_generations} distinct generation levels, labeled 1 through {num_generations}, with the rule that whenever someone appears as a daughter and also (in another photo) as a middle person, her generation as a daughter is exactly one less than her generation as a middle person. Additionally, any individual male who appears in the left position may do so in at most {left_capacity} different photos. Among all albums obeying these rules, determine the minimum possible number of distinct people that must appear in the album.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose parameters to ensure non-trivial DP and feasible runtime
# num_photos: moderate size so DP is tractable but nontrivial
n = rng.randint(24, 45)
# num_generations: at least 3 and at most 8, and less than n
k = rng.randint(3, min(8, n-2))
# left_capacity: small to enforce meaningful constraints but avoid triviality
L = rng.choice([2, 3, 4])
# Rarely bump n larger with care
if rng.random() < 0.1:
    n = rng.randint(30, 50)
    k = rng.randint(4, min(8, n-3))
    L = rng.choice([2, 3])
return {
    'num_photos': n,
    'num_generations': k,
    'left_capacity': L
}

    def verifier(assign):
# Validate keys
if not all(key in assign for key in ('num_photos', 'num_generations', 'left_capacity')):
    # Missing keys
    return (False, None)  # Missing required assignment keys
n = assign['num_photos']
k = assign['num_generations']
L = assign['left_capacity']
# Domain checks
if not (isinstance(n, int) and isinstance(k, int) and isinstance(L, int)):
    return (False, None)  # Types must be integers
if n < 3:
    return (False, None)  # Too few photos to be meaningful
if k < 2 or k > n:
    return (False, None)  # At least 2 levels, and cannot exceed n
if L < 1:
    return (False, None)  # Capacity must be positive
# Enforce non-triviality: make sure parameters avoid degenerate cases
if k < 3:
    return (False, None)  # To ensure difficulty, require >=3 levels
if L > max(4, n//3):
    return (False, None)  # Capacity too large; would trivialize reuse constraint
# Define the lower-bound function f as in the seed, generalized
def f(x, y):
    d = x - y
    if d >= 2:
        return d
    elif d == 1:
        return 2
    else:
        return 1
def ceil_div(a, b):
    return (a + b - 1) // b
def g(x, y, L):
    # Incorporate left-capacity constraint alongside structural f-bound
    return max(f(x, y), ceil_div(x, L))
# DP to minimize S = sum_{i=1..k} g(a_i, a_{i+1}, L) subject to a_i>=1, sum a_i = n, a_{k+1}=0
from functools import lru_cache
@lru_cache(maxsize=None)
def dp(pos, rem, prev):
    # pos is 1-indexed position among a_1..a_k
    # rem is remaining sum to allocate across positions pos..k
    # prev is a_{pos-1} (None if pos==1)
    if pos == k:
        # last position: a_k must be rem >=1
        if rem < 1:
            return float('inf')
        a_k = rem
        cost_prev = 0 if prev is None else g(prev, a_k, L)
        cost_last = g(a_k, 0, L)
        return cost_prev + cost_last
    # choose a_current between 1 and rem - (k - pos), ensuring at least 1 left per remaining position
    max_a = rem - (k - pos)
    if max_a < 1:
        return float('inf')
    best = float('inf')
    # iterate possible allocations
    for a in range(1, max_a + 1):
        cost_prev = 0 if prev is None else g(prev, a, L)
        val = cost_prev + dp(pos + 1, rem - a, a)
        if val < best:
            best = val
    return best
S_min = dp(1, n, None)
if S_min == float('inf'):
    return (False, None)  # infeasible allocation
# The minimal number of distinct people equals:
#   (number of daughters/right persons) + (minimal number of distinct left males required)
# Middle persons can be arranged to be among the daughters across generations under optimal constructions.
answer = n + S_min
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

